61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    private final OwnerFieldsValidator ownerFieldsValidator;
77	
78	    private final PostcodeValidator postcodeValidator;
79	
80	    private final TelephoneNormalizer telephoneNormalizer;
81	
82	    private final EmailNormalizer emailNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    private final BusinessDayResolver businessDayResolver;
87	
88	    private final OwnerAuditLogger ownerAuditLogger;
89	
90	    /** Maximum number of owners a single city may hold before further creations are rejected. */
91	    static final long MAX_OWNERS_PER_CITY = 50;
92	
93	    /** Maximum number of owners that may be registered on a single day before further creations are rejected. */
94	    static final long MAX_OWNERS_PER_DAY = 100;
95	
96	    /** Number of owners already registered on a day above which a new owner is flagged with a bulk-signup warning. */
97	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper,
103	                                 OwnerFieldsValidator ownerFieldsValidator,
104	                                 PostcodeValidator postcodeValidator,
105	                                 TelephoneNormalizer telephoneNormalizer,
106	                                 EmailNormalizer emailNormalizer,
107	                                 AddressNormalizer addressNormalizer,
108	                                 BusinessDayResolver businessDayResolver,
109	                                 OwnerAuditLogger ownerAuditLogger) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	        this.ownerFieldsValidator = ownerFieldsValidator;
115	        this.postcodeValidator = postcodeValidator;
116	        this.telephoneNormalizer = telephoneNormalizer;
117	        this.emailNormalizer = emailNormalizer;
118	        this.addressNormalizer = addressNormalizer;
119	        this.businessDayResolver = businessDayResolver;
120	        this.ownerAuditLogger = ownerAuditLogger;
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
152	        this.ownerFieldsValidator.validate(ownerFieldsDto);
153	        this.postcodeValidator.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
154	        HttpHeaders headers = new HttpHeaders();
155	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
156	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
157	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
158	        LocalDate serverDate = LocalDate.now();
159	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
160	            throw new FutureRegistrationDateException(owner.getRegistrationDate(), serverDate);
161	        }
162	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : serverDate;
163	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
164	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
165	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
166	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
167	        }
168	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
169	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
170	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
171	        }
172	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
173	            this.clinicService.joinHousehold(owner);
174	        }
175	        if (!this.clinicService.findOwnersByIdentityKey(owner.getIdentityKey()).isEmpty()) {
176	            throw new DuplicateOwnerIdentityException(owner.getIdentityKey());
177	        }
178	        Owner possibleDuplicate = this.clinicService.findPossibleDuplicateOf(owner);
179	        if (possibleDuplicate != null) {
180	            owner.setPossibleDuplicateOf(possibleDuplicate.getId());
181	        }
182	        this.clinicService.saveOwner(owner);
183	        this.ownerAuditLogger.logCreated(owner);
184	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
185	        headers.setLocation(UriComponentsBuilder.newInstance()
186	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
187	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
188	    }
