16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "birth_date")
58	    private LocalDate birthDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "membership_number")
70	    private String membershipNumber;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @Column(name = "postcode")
79	    private String postcode;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getTelephone() {
104	        return this.telephone;
105	    }
106	
107	    public void setTelephone(String telephone) {
108	        this.telephone = telephone;
109	    }
110	
111	    public String getEmail() {
112	        return this.email;
113	    }
114	
115	    public void setEmail(String email) {
116	        this.email = email;
117	    }
118	
119	    public LocalDate getRegistrationDate() {
120	        return this.registrationDate;
121	    }
122	
123	    public void setRegistrationDate(LocalDate registrationDate) {
124	        this.registrationDate = registrationDate;
125	    }
126	
127	    public LocalDate getBirthDate() {
128	        return this.birthDate;
129	    }
130	
131	    public void setBirthDate(LocalDate birthDate) {
132	        this.birthDate = birthDate;
133	    }
134	
135	    public String getCustomerCode() {
136	        return this.customerCode;
137	    }
138	
139	    public void setCustomerCode(String customerCode) {
140	        this.customerCode = customerCode;
141	    }
142	
143	    public String getHouseholdId() {
144	        return this.householdId;
145	    }
146	
147	    public void setHouseholdId(String householdId) {
148	        this.householdId = householdId;
149	    }
150	
151	    public Integer getNamesakeCount() {
152	        return this.namesakeCount;
153	    }
154	
155	    public void setNamesakeCount(Integer namesakeCount) {
156	        this.namesakeCount = namesakeCount;
157	    }
158	
159	    public String getMembershipNumber() {
160	        return this.membershipNumber;
161	    }
162	
163	    public void setMembershipNumber(String membershipNumber) {
164	        this.membershipNumber = membershipNumber;
165	    }
166	
167	    /**
168	     * Whether this owner was created after more than 80 owners had already been registered on the
169	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
170	     */
171	    public Boolean getBulkSignupWarning() {
172	        return this.bulkSignupWarning;
173	    }
174	
175	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
176	        this.bulkSignupWarning = bulkSignupWarning;
177	    }
178	
179	    /**
180	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
181	     * counting this owner) captured once at creation.
182	     */
183	    public Integer getHouseholdSize() {
184	        return this.householdSize;
185	    }
186	
187	    public void setHouseholdSize(Integer householdSize) {
188	        this.householdSize = householdSize;
189	    }
190	
191	    /**
192	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
193	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
194	     */
195	    public String getPostcode() {
196	        return this.postcode;
197	    }
198	
199	    public void setPostcode(String postcode) {
200	        this.postcode = postcode;
201	    }
202	
203	    /**
204	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
205	     * creation, or {@code null} when none. A soft duplicate shares an existing owner's last name and
206	     * postcode but has a different telephone (so it is not a hard {@link #getIdentityKey() identity}
207	     * duplicate). Captured once at creation.
208	     */
209	    public Integer getPossibleDuplicateOf() {
210	        return this.possibleDuplicateOf;
211	    }
212	
213	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
214	        this.possibleDuplicateOf = possibleDuplicateOf;
215	    }
216	
217	    /**
218	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
219	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
220	     */
221	    @Transient
222	    public Boolean getPossibleDuplicate() {
223	        return this.possibleDuplicateOf != null;
224	    }
225	
226	    /**
227	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
228	     */
229	    @Transient
230	    public String getDisplayName() {
231	        return this.getLastName() + ", " + this.getFirstName();
232	    }
233	
234	    /**
235	     * Return this owner's initials as the upper-cased first letters of the first and last
236	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
237	     */
238	    @Transient
239	    public String getInitials() {
240	        return initial(this.getFirstName()) + initial(this.getLastName());
241	    }
242	
243	    private static String initial(String name) {
244	        return Character.toUpperCase(name.charAt(0)) + ".";
245	    }
246	
247	    /** The membership level every owner starts at on creation. */
248	    private static final int BASE_MEMBERSHIP_LEVEL = 1;
249	
250	    /** The highest membership level derivable at creation; level 4 is reserved for tenure. */
251	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
252	
253	    /**
254	     * Return this owner's membership level, a number from 1 to 3 derived at creation: every owner
255	     * starts at {@value #BASE_MEMBERSHIP_LEVEL}; add 1 when an email address is present; add 1 when
256	     * the owner has no namesakes ({@code namesakeCount} is 0); capped at
257	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
258	     */
259	    @Transient
260	    public Integer getMembershipLevel() {
261	        int level = BASE_MEMBERSHIP_LEVEL;
262	        if (hasEmail()) {
263	            level++;
264	        }
265	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
266	            level++;
267	        }
268	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
269	    }
270	
271	    /** Whether this owner has a usable email address (present and not blank). */
272	    private boolean hasEmail() {
273	        return this.email != null && !this.email.isBlank();
274	    }
275	
276	    /**
277	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
278	     * present, otherwise {@code "PHONE"}.
279	     */
280	    @Transient
281	    public String getContactPreference() {
282	        return hasEmail() ? "EMAIL" : "PHONE";
283	    }
284	
285	    /**
286	     * Return this owner's age band derived from the {@code birthDate} as of the
287	     * {@code registrationDate}, or {@code null} when no birth date is known.
288	     */
289	    @Transient
290	    public AgeBand getAgeBand() {
291	        if (this.birthDate == null || this.registrationDate == null) {
292	            return null;
293	        }
294	        return AgeBand.asOf(this.birthDate, this.registrationDate);
295	    }
296	
297	    /**
298	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
299	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
300	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
301	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
302	     * region is resolved directly from the postcode and city.
303	     */
304	    @Transient
305	    public String getLocality() {
306	        if (this.customerCode == null) {
307	            return LocalityResolver.regionFor(this.postcode, this.city);
308	        }
309	        int separator = this.customerCode.indexOf('-');
310	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
311	    }
312	
313	    /**
314	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
315	     * {@code customerCode}.
316	     */
317	    @Transient
318	    public Integer getCheckDigit() {
319	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
320	    }
321	
322	    /**
323	     * Return this owner's identity key, the single derived value all duplicate detection is based
324	     * on: the normalized telephone, email and household id joined with {@code '|'} as
325	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
326	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
327	     * because the telephone is part of the key, members of one household (same {@code householdId})
328	     * with different telephones have distinct keys and are not duplicates.
329	     */
330	    @Transient
331	    public String getIdentityKey() {
332	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
333	    }
334	
335	    private static String keyPart(String value) {
336	        return value == null ? "" : value;
337	    }
338	
339	    protected Set<Pet> getPetsInternal() {
340	        if (this.pets == null) {
341	            this.pets = new HashSet<>();
342	        }
343	        return this.pets;
344	    }
345	
346	    protected void setPetsInternal(Set<Pet> pets) {
347	        this.pets = pets;
348	    }
349	
350	    public List<Pet> getPets() {
351	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
352	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
353	        return Collections.unmodifiableList(sortedPets);
354	    }
355	
356	    public void setPets(List<Pet> pets) {
357	        this.pets = new HashSet<>(pets);
358	    }
359	
360	    public void addPet(Pet pet) {
361	        getPetsInternal().add(pet);
362	        pet.setOwner(this);
363	    }
364	
365	    /**
366	     * Return the Pet with the given name, or null if none found for this Owner.
367	     *
368	     * @param name to test
369	     * @return true if pet name is already in use
370	     */
371	    public Pet getPet(String name) {
372	        return getPet(name, false);
373	    }
374	
375	    /**
376	     * Return the Pet with the given name, or null if none found for this Owner.
377	     *
378	     * @param name to test
379	     * @return true if pet name is already in use
380	     */
381	    public Pet getPet(String name, boolean ignoreNew) {
382	        name = name.toLowerCase();
383	        for (Pet pet : getPetsInternal()) {
384	            if (!ignoreNew || !pet.isNew()) {
385	                String compName = pet.getName();
386	                compName = compName.toLowerCase();
387	                if (compName.equals(name)) {
388	                    return pet;
389	                }
390	            }
391	        }
392	        return null;
393	    }
394	
395	    public Pet getPet(Integer petId) {
396	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
397	    }
398	
399	    @Override
400	    public String toString() {
401	        return new ToStringCreator(this)
402	
403	            .append("id", this.getId())
404	            .append("new", this.isNew())
405	            .append("lastName", this.getLastName())
406	            .append("firstName", this.getFirstName())
407	            .append("address", this.address)
408	            .append("city", this.city)
409	            .append("telephone", this.telephone)
410	            .append("email", this.email)
411	            .append("registrationDate", this.registrationDate)
412	            .toString();
413	    }
414	}
